describe('Category Assignment via Dropdown', () => {
  beforeEach(() => {
    cy.visit('/records');
  });

  it('should successfully assign a category to a record via dropdown', () => {
    // Intercept the API call for category assignment
    cy.intercept('POST', '/api/records/*/assign-category').as('assignCategory');

    // Click on a record to open details
    cy.get('[data-testid="record-row-1"]').click();

    // Verify record details are visible
    cy.get('[data-testid="record-details"]').should('be.visible');

    // Verify category dropdown is visible and has options
    cy.get('[data-testid="category-dropdown"]').should('be.visible');
    cy.get('[data-testid="category-dropdown option"]').should('have.length.greaterThan', 0);

    // Select a category from the dropdown
    cy.get('[data-testid="category-dropdown"]').select('Work');

    // Verify selected value is displayed
    cy.get('[data-testid="selected-category-display"]').should('contain', 'Work');

    // Click the assign button
    cy.get('[data-testid="assign-category-button"]').click();

    // Wait for the API call to complete
    cy.wait('@assignCategory');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Category assigned successfully');

    // Verify the record now has the assigned category
    cy.get('[data-testid="record-category-badge"]').should('be.visible').should('contain', 'Work');
  });

  it('should handle unassigning a category when dropdown is empty', () => {
    // Intercept the API call for unassigning category
    cy.intercept('POST', '/api/records/*/unassign-category').as('unassignCategory');

    // Click on a record with an existing category
    cy.get('[data-testid="record-row-2"]').click();

    // Verify category is currently assigned
    cy.get('[data-testid="record-category-badge"]').should('be.visible').should('contain', 'Personal');

    // Open category dropdown
    cy.get('[data-testid="category-dropdown"]').click();

    // Select 'None' or clear the selection
    cy.get('[data-testid="category-dropdown option[value=\"none\"]').click();

    // Verify selected value is 'None'
    cy.get('[data-testid="selected-category-display"]').should('contain', 'None');

    // Click the unassign button
    cy.get('[data-testid="unassign-category-button"]').click();

    // Wait for the API call
    cy.wait('@unassignCategory');

    // Verify success message for unassigning
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Category unassigned successfully');

    // Verify category badge is removed or shows 'Uncategorized'
    cy.get('[data-testid="record-category-badge"]').should('not.exist');
    cy.get('[data-testid="record-category-status"]').should('contain', 'Uncategorized');
  });
});
